#include <Servo.h>
Servo myServo;
// Motor TERM_A → Pin ~3, TERM_B → GND
int LM = 2;
int RM = 3;
const int IR_SENSOR_PIN = 6;
const int trigPin = 4;   
const int echoPin = 5;  
const int distanceThreshold = 20; 
void setup() {
Serial.begin(9600);
  pinMode(IR_SENSOR_PIN, INPUT);       
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  myServo.attach(7);
  pinMode(LM, OUTPUT);
pinMode(RM, OUTPUT);
}

void loop() {
 analogWrite(LM, 220)
analogWrite(RM, 220);
  delay(1000);
analogWrite(LM, 0);
analogWrite(RM, 220);
  delay(1000);
analogWrite(LM, 220);
analogWrite(RM, 220);
  delay(1000);
  for (int angle = 0; angle <= 180; angle += 5) {
    myServo.write(angle);
    delay(30);
  }
  for (int angle = 180; angle >= 0; angle -= 5) {
    myServo.write(angle);
    delay(30);
  }
 long duration;
  int distance;

  // Send ultrasonic pulse
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Read echo time
  duration = pulseIn(echoPin, HIGH, 30000UL); // Timeout after 30ms (~5m range)

  // Calculate distance in cm
  if (duration == 0) {
    // No echo received (out of range)
    distance = -1;
  } else {
    distance = duration * 0.034 / 2; // Speed of sound: 0.034 cm/µs
  }

  // Print distance
  if (distance != -1) {
    Serial.print("Distance: ");
    Serial.print(distance);
    Serial.println(" cm");
  } else {
    Serial.println("Out of range");
  }
 int sensorState = digitalRead(IR_SENSOR_PIN);

  // Most IR obstacle sensors output LOW when object is detected
  if (sensorState == LOW) {
    Serial.println("Hand detected!");
  } else {
    Serial.println("No hand detected.");
  }

  delay(100); // Small delay for stability
}
